class InputBuffer {
    constructor(bufferTime = 100) {
        this.bufferTime = bufferTime; // ms
        this.buffer = [];
    }

    add(action) {
        this.buffer.push({ action, time: performance.now() });
    }

    consume(action) {
        const now = performance.now();
        // Find unexpired input
        const idx = this.buffer.findIndex(
            b => b.action === action && (now - b.time) < this.bufferTime
        );

        if (idx !== -1) {
            this.buffer.splice(idx, 1);
            return true;
        }
        return false;
    }

    update() {
        // Clean expired inputs
        const now = performance.now();
        this.buffer = this.buffer.filter(
            b => (now - b.time) < this.bufferTime
        );
    }
}

// Usage: Buffer jump input
if (input.isPressed('Space')) inputBuffer.add('jump');

// In physics update
if (player.onGround && inputBuffer.consume('jump')) {
    player.jump();
}
